actionConfiguration.body:
async () => {
  try {
    const response = await _api_v1_auth_login.run({
      username: Username.text,
      password: Password.text
    });
    if (response && response.access_token) {
      await storeValue('access_token', response.access_token);
      await storeValue('refresh_token', response.refresh_token);
      await storeValue('token_type', response.token_type || 'bearer');
      await storeValue('token_expiry', response.expires_in ? new Date(Date.now() + response.expires_in * 1000).toISOString() : null);
      await storeValue('isLoggedIn', true);
      await storeValue('lastTokenRefresh', Date.now());
      AuthHelper.setupAutoRefresh();
      showAlert('Login successful.', 'success');
      setTimeout(() => {
        navigateTo('dashboard');
      }, 2000);
    } else {
      showAlert('Login failed. Please try again.', 'error');
    }
  } catch (error) {
    showAlert('Login failed: ' + error.message, 'error');
  }
}

