actionConfiguration.body:
async () => {
  if (!AuthHelper.isAuthenticated()) {
    AuthHelper.redirectToLogin();
    return;
  }
  if (AuthHelper.isTokenExpired()) {
    const newToken = await AuthHelper.refreshToken();
    if (!newToken) {
      return;
    }
  }
  AuthHelper.setupAutoRefresh();
  try {
    const profile = await ApiClient.call(GetUserProfileQuery);
    if (profile) {
      await AuthHelper.setUserProfile(profile);
      if (appsmith.store.mustChangePassword === true) {
        AuthHelper.redirectToChangePassword();
        return;
      }
      if (appsmith.store.isActive === false) {
        showAlert('Your account is inactive. Please contact support.', 'error');
        return;
      }
    }
  } catch (error) {
    console.error('Failed to load profile:', error);
    return;
  }
  try {
    await ApiClient.call(GetAnalyses);
  } catch (error) {
    console.error('Failed to load dashboard data:', error);
  }
}

