actionConfiguration.body:
error => {
  if (error.status === 401) {
    AuthHelper.redirectToLogin();
    return 'Session expired. Please login again.';
  }
  if (error.status === 403) {
    const errorDetail = error.response?.data?.detail || error.message || '';
    if (errorDetail.includes('Password change required') || error.response?.headers?.['x-password-change-required'] === 'true') {
      AuthHelper.redirectToChangePassword();
      return 'Password change required. Please update your password.';
    }
    if (errorDetail.includes('User is not active')) {
      AuthHelper.redirectToDashboard();
      return 'Your account is inactive. Please contact support.';
    }
    if (errorDetail.includes('Admin privileges required')) {
      AuthHelper.redirectToDashboard();
      return 'Admin privileges required.';
    }
    AuthHelper.redirectToDashboard();
    return 'Permission denied.';
  }
  return error.message || 'An unexpected error occurred.';
}

