  if (AuthHelper.isAuthenticated() && !AuthHelper.isTokenExpired()) {
    AuthHelper.setupAutoRefresh();
    return true;
  } else if (AuthHelper.isAuthenticated() && AuthHelper.isTokenExpired()) {
    const newToken = await AuthHelper.refreshToken();
    if (newToken) {
      AuthHelper.setupAutoRefresh();
      return true;
    }
  }
  return false;
}

