async () => {
  if (!title.text?.trim()) {
    showAlert('Please enter a title', 'error');
    return;
  }
  if (!text.text?.trim()) {
    showAlert('Please enter document text', 'error');
    return;
  }
  CreateAnalysisPage.isProcessing = true;
  CreateAnalysisPage.pollAttempts = 0;
  showModal(Analysis_Creation.name);
  try {
    const response = await ApiClient.call(CreateAnalysisQuery, {
      title: title.text,
      description: description.text || '',
      text: text.text
    });
    if (response && response.task_id) {
      CreateAnalysisPage.taskId = response.task_id;
      CreateAnalysisPage.startPolling();
    } else {
      throw new Error('No task ID received');
    }
  } catch (error) {
    console.error('Failed to create analysis:', error);
    CreateAnalysisPage.isProcessing = false;
    closeModal(Analysis_Creation.name);
    showAlert('Failed to create analysis: ' + error.message, 'error');
  }
}

