actionConfiguration.body:
async (apiFunction, params = {}) => {
  const token = await AuthHelper.getValidToken();
  if (!token) {
    return null;
  }
  try {
    return await apiFunction.run(params);
  } catch (error) {
    if (error.status === 401) {
      AuthHelper.redirectToLogin();
      throw error;
    }
    if (error.status === 403) {
      const errorDetail = error.response?.data?.detail || error.message || '';
      if (errorDetail.includes('Password change required') || error.response?.headers?.['x-password-change-required'] === 'true') {
        AuthHelper.redirectToChangePassword();
        throw error;
      }
      if (errorDetail.includes('User is not active')) {
        showAlert('Your account is inactive. Please contact support.', 'error');
        AuthHelper.redirectToDashboard();
        throw error;
      }
      if (errorDetail.includes('Admin privileges required')) {
        showAlert('Admin privileges required to access this resource.', 'error');
        AuthHelper.redirectToDashboard();
        throw error;
      }
      showAlert('You don\'t have permission to perform this action.', 'error');
      AuthHelper.redirectToDashboard();
      throw error;
    }
    throw error;
  }
}

