actionConfiguration.body:
async () => {
  if (!CreateAnalysisPage.taskId) {
    return;
  }
  CreateAnalysisPage.pollAttempts++;
  if (CreateAnalysisPage.pollAttempts > CreateAnalysisPage.maxPollAttempts) {
    clearInterval(CreateAnalysisPage.statusCheckInterval);
    CreateAnalysisPage.statusCheckInterval = null;
    CreateAnalysisPage.isProcessing = false;
    closeModal(Analysis_Creation.name);
    showAlert('Analysis is taking too long. Please check later.', 'warning');
    return;
  }
  try {
    const statusResponse = await ApiClient.call(AnalysisStatusQuery, {
      task_id: CreateAnalysisPage.taskId
    });
    if (!statusResponse) {
      return;
    }
    const status = statusResponse.status;
    if (status === 'completed') {
      clearInterval(CreateAnalysisPage.statusCheckInterval);
      CreateAnalysisPage.statusCheckInterval = null;
      CreateAnalysisPage.isProcessing = false;
      closeModal(Analysis_Creation.name);
      showAlert('Analysis completed successfully!', 'success');
      if (statusResponse.analysis && statusResponse.analysis.id) {
        const analysisId = statusResponse.analysis.id;
        navigateTo('detailed analysis', {
          analysis_id: analysisId
        });
        storeValue('analysisId', analysisId);
      } else {
        navigateTo('dashboard');
      }
    } else if (status === 'failed') {
      clearInterval(CreateAnalysisPage.statusCheckInterval);
      CreateAnalysisPage.statusCheckInterval = null;
      CreateAnalysisPage.isProcessing = false;
      closeModal(Analysis_Creation.name);
      const errorMsg = statusResponse.error || 'Analysis failed';
      showAlert('Analysis failed: ' + errorMsg, 'error');
    }
  } catch (error) {
    console.error('Failed to check status:', error);
    if (error.status !== 404) {
      if (CreateAnalysisPage.pollAttempts > 10) {
        clearInterval(CreateAnalysisPage.statusCheckInterval);
        CreateAnalysisPage.statusCheckInterval = null;
        CreateAnalysisPage.isProcessing = false;
        closeModal(Analysis_Creation.name);
        showAlert('Error checking analysis status. Please refresh.', 'error');
      }
    }
  }
}

