export default {
  onPageLoad: () => {
    // Step 1: Check authentication
    if (!AuthHelper.isAuthenticated()) {
      AuthHelper.redirectToLogin();
      return;
    }

    // Step 2: Check token
    if (AuthHelper.isTokenExpired()) {
      AuthHelper.refreshToken();
      return;
    }

    // Step 3: If user doesn't need password change, redirect to dashboard
    if (appsmith.store.mustChangePassword === false) {
      navigateTo('dashboard');
      return;
    }

    // Step 4: Setup auto-refresh
    AuthHelper.setupAutoRefresh();
  },

  onChangePassword: async () => {
    try {
      const response = await changePasswordAPI.run({
        current_password: old_password.text,
        new_password: new_password.text
      });

      if (response && response.success) {
        showAlert('Password changed successfully!', 'success');

        // Update user state
        await storeValue('mustChangePassword', false);
        if (appsmith.store.user) {
          const user = appsmith.store.user;
          user.must_change_password = false;
          await storeValue('user', user);
        }

        // Navigate to dashboard
        navigateTo('dashboard');
      } else {
        showAlert('Password change failed. Please try again.', 'error');
      }
    } catch (error) {
      if (error.status === 403) {
        const errorDetail = error.response?.data?.detail || '';
        if (errorDetail.includes('Password change required')) {
          showAlert('Please change your password.', 'warning');
        } else {
          showAlert('Error: ' + errorDetail, 'error');
        }
      } else {
        showAlert('Password change failed: ' + error.message, 'error');
      }
    }
  }
}

