export default {
	// Check if user is authenticated
	isAuthenticated: () => {
		return !!appsmith.store.access_token;
	},

	// Check if token is expired
	isTokenExpired: () => {
		if (!appsmith.store.token_expiry) return true;
		const now = Date.now();
		const expiry = new Date(appsmith.store.token_expiry).getTime();
		// Add 60 second buffer to refresh early
		return now >= (expiry - 60000);
	},

	// Refresh the access token using refresh token
	refreshToken: async () => {
		if (!appsmith.store.refresh_token) {
			AuthHelper.redirectToLogin();
			return null;
		}

		try {
			const response = await refreshTokenAPI.run();
			if (response && response.access_token) {
				// Store new tokens using storeValue
				await storeValue('access_token', response.access_token);
				await storeValue('refresh_token', response.refresh_token);
				await storeValue('token_type', response.token_type || 'bearer');
				await storeValue('token_expiry', response.expires_in ? 
												 new Date(Date.now() + response.expires_in * 1000).toISOString() : 
												 null);
				await storeValue('lastTokenRefresh', Date.now());
				await storeValue('isLoggedIn', true);

				return response.access_token;
			} else {
				AuthHelper.redirectToLogin();
				return null;
			}
		} catch (error) {
			console.error('Token refresh failed:', error);
			// If refresh fails, redirect to login
			AuthHelper.redirectToLogin();
			return null;
		}
	},

	// Redirect to login page
	redirectToLogin: () => {
		// Clear all auth data using storeValue
		storeValue('access_token', null);
		storeValue('refresh_token', null);
		storeValue('token_type', null);
		storeValue('token_expiry', null);
		storeValue('user', null);
		storeValue('isLoggedIn', false);
		storeValue('lastTokenRefresh', null);
		storeValue('userRole', null);
		storeValue('mustChangePassword', null);
		storeValue('isActive', null);

		// Clear any refresh interval
		if (appsmith.store._refreshInterval) {
			clearInterval(appsmith.store._refreshInterval);
			storeValue('_refreshInterval', null);
		}

		// Navigate to login page
		navigateTo('Login');
	},

	// Redirect to change password page
	redirectToChangePassword: () => {
		navigateTo('change password');
	},

	// Redirect to dashboard (for forbidden access)
	redirectToDashboard: () => {
		navigateTo('dashboard');
	},

	// Get valid token (auto-refreshes if needed)
	getValidToken: async () => {
		if (!AuthHelper.isAuthenticated()) {
			AuthHelper.redirectToLogin();
			return null;
		}

		// If token is expired or about to expire, refresh it
		if (AuthHelper.isTokenExpired()) {
			const newToken = await AuthHelper.refreshToken();
			return newToken;
		}

		return appsmith.store.access_token;
	},

	// Logout function
	logout: async () => {
		// Clear all auth data using storeValue
		storeValue('access_token', null);
		storeValue('refresh_token', null);
		storeValue('token_type', null);
		storeValue('token_expiry', null);
		storeValue('user', null);
		storeValue('isLoggedIn', false);
		storeValue('lastTokenRefresh', null);
		storeValue('userRole', null);
		storeValue('mustChangePassword', null);
		storeValue('isActive', null);

		// Clear interval
		if (appsmith.store._refreshInterval) {
			clearInterval(appsmith.store._refreshInterval);
			storeValue('_refreshInterval', null);
		}

		navigateTo('Login');
	},

	// Setup periodic token refresh
	setupAutoRefresh: () => {
		// Clear any existing interval
		if (appsmith.store._refreshInterval) {
			clearInterval(appsmith.store._refreshInterval);
			storeValue('_refreshInterval', null);
		}

		// Check token status every minute
		const intervalId = setInterval(async () => {
			if (!AuthHelper.isAuthenticated()) {
				return;
			}

			const expiryTime = appsmith.store.token_expiry ? 
						new Date(appsmith.store.token_expiry).getTime() : 
			null;

			if (expiryTime) {
				const timeUntilExpiry = expiryTime - Date.now();
				// If token expires in less than 5 minutes, refresh it
				if (timeUntilExpiry < 300000) { // 5 minutes
					console.log('Token expiring soon, refreshing...');
					await AuthHelper.refreshToken();
				}
			}
		}, 60000); // Check every minute

		// Store interval ID in appsmith.store
		storeValue('_refreshInterval', intervalId);
	},

	// Get authorization header for API calls
	getAuthHeader: async () => {
		const token = await AuthHelper.getValidToken();
		if (!token) return null;

		const tokenType = appsmith.store.token_type || 'bearer';
		return {
			'Authorization': `${tokenType.charAt(0).toUpperCase() + tokenType.slice(1)} ${token}`,
			'Content-Type': 'application/json'
		};
	},

	// Initialize auth state on app load
	initialize: async () => {
		// Check if we have a valid token
		if (AuthHelper.isAuthenticated() && !AuthHelper.isTokenExpired()) {
			// Setup auto-refresh
			AuthHelper.setupAutoRefresh();
			return true;
		} else if (AuthHelper.isAuthenticated() && AuthHelper.isTokenExpired()) {
			// Token exists but expired, try to refresh
			const newToken = await AuthHelper.refreshToken();
			if (newToken) {
				AuthHelper.setupAutoRefresh();
				return true;
			}
		}
		return false;
	},

	// Set user data from profile
	setUserProfile: async (profileData) => {
		await storeValue('user', profileData);
		await storeValue('userRole', profileData.role);
		await storeValue('mustChangePassword', profileData.must_change_password);
		await storeValue('isActive', profileData.is_active);

		// Check user state
		return AuthHelper.checkUserState();
	},

	// Check and handle user state
	checkUserState: () => {
		const isActive = appsmith.store.isActive;
		const mustChangePassword = appsmith.store.mustChangePassword;

		// Check if user is inactive
		if (isActive === false) {
			showAlert('Your account is inactive. Please contact support.', 'error');
			AuthHelper.redirectToDashboard();
