			CreateAnalysisPage.statusCheckInterval = null;
		}

		CreateAnalysisPage.isProcessing = false;
		CreateAnalysisPage.taskId = null;
		CreateAnalysisPage.pollAttempts = 0;

		closeModal(Analysis_Creation.name);
		showAlert('Analysis cancelled', 'info');
	},

	// Check if analysis is in progress
	isInProgress: () => {
		return CreateAnalysisPage.isProcessing;
	}
}

