export default {
	// Make authenticated API call
	call: async (apiFunction, params = {}) => {
		// Get valid token (auto-refreshes if needed)
		const token = await AuthHelper.getValidToken();
		if (!token) {
			return null;
		}

		try {
			// For Appsmith queries, the token is added via headers
			return await apiFunction.run(params);
		} catch (error) {
			// Handle authentication errors
			if (error.status === 401) {
				// Token expired or invalid - redirect to login
				AuthHelper.redirectToLogin();
				throw error;
			}

			if (error.status === 403) {
				// Handle different 403 scenarios
				const errorDetail = error.response?.data?.detail || error.message || '';

				// Check for password change required
				if (errorDetail.includes('Password change required') || 
						error.response?.headers?.['x-password-change-required'] === 'true') {
					// Redirect to change password page
					AuthHelper.redirectToChangePassword();
					throw error;
				}

				// Check for inactive user
				if (errorDetail.includes('User is not active')) {
					showAlert('Your account is inactive. Please contact support.', 'error');
					AuthHelper.redirectToDashboard();
					throw error;
				}

				// Check for admin privileges required
				if (errorDetail.includes('Admin privileges required')) {
					showAlert('Admin privileges required to access this resource.', 'error');
					AuthHelper.redirectToDashboard();
					throw error;
				}

				// Other 403 errors - redirect to dashboard
				showAlert('You don\'t have permission to perform this action.', 'error');
				AuthHelper.redirectToDashboard();
				throw error;
			}

			// Re-throw other errors
			throw error;
		}
	},

	// Get headers for manual API calls
	getHeaders: async () => {
		const token = await AuthHelper.getValidToken();
		if (!token) return null;

		const tokenType = appsmith.store.token_type || 'bearer';
		return {
			'Authorization': `${tokenType.charAt(0).toUpperCase() + tokenType.slice(1)} ${token}`,
			'Content-Type': 'application/json'
		};
	},

	// Handle API errors without making a call
	handleError: (error) => {
		if (error.status === 401) {
			AuthHelper.redirectToLogin();
			return 'Session expired. Please login again.';
		}

		if (error.status === 403) {
			const errorDetail = error.response?.data?.detail || error.message || '';

			if (errorDetail.includes('Password change required') || 
					error.response?.headers?.['x-password-change-required'] === 'true') {
				AuthHelper.redirectToChangePassword();
				return 'Password change required. Please update your password.';
			}

			if (errorDetail.includes('User is not active')) {
				AuthHelper.redirectToDashboard();
				return 'Your account is inactive. Please contact support.';
			}

			if (errorDetail.includes('Admin privileges required')) {
				AuthHelper.redirectToDashboard();
				return 'Admin privileges required.';
			}

			AuthHelper.redirectToDashboard();
			return 'Permission denied.';
		}

		return error.message || 'An unexpected error occurred.';
	}
}

