			'Content-Type': 'application/json'
		};
	},

	// Handle API errors without making a call
	handleError: (error) => {
		if (error.status === 401) {
			AuthHelper.redirectToLogin();
			return 'Session expired. Please login again.';
		}

		if (error.status === 403) {
			const errorDetail = error.response?.data?.detail || error.message || '';

			if (errorDetail.includes('Password change required') || 
					error.response?.headers?.['x-password-change-required'] === 'true') {
				AuthHelper.redirectToChangePassword();
				return 'Password change required. Please update your password.';
