export default {
  onPageLoad: async () => {
    // Step 1: Check authentication
    if (!AuthHelper.isAuthenticated()) {
      AuthHelper.redirectToLogin();
      return;
    }

    // Step 2: Check token
    if (AuthHelper.isTokenExpired()) {
      const newToken = await AuthHelper.refreshToken();
      if (!newToken) {
        return;
      }
    }

    // Step 3: Setup auto-refresh
    AuthHelper.setupAutoRefresh();

    // Step 4: Check user state (must_change_password and is_active)
    if (!AuthHelper.checkUserState()) {
      return; // redirect handled by checkUserState
    }

    // Step 5: Check admin access
    if (!AuthHelper.checkAdminAccess()) {
      return; // redirect handled by checkAdminAccess
    }

    // Step 6: Load user list data
    try {
      const users = await ApiClient.call(GetUserListQuery);
      // Process and display user list...
    } catch (error) {
      console.error('Failed to load user list:', error);
    }
  }
}

